  const files = new Map(await Promise.all(['index.html','style.css','src/app.mjs','src/domain.mjs'].map(async file => ['/'+file, await readFile(file,'utf8')])));
  await page.route('http://127.0.0.1:4350/**', route => {
    const path = new URL(route.request().url()).pathname;
    const file = path === '/' ? '/index.html' : path;
    return route.fulfill({status: files.has(file)?200:404, contentType:file.endsWith('.mjs')?'text/javascript':file.endsWith('.css')?'text/css':'text/html', body:files.get(file)??''});
  });
  await page.goto('http://127.0.0.1:4350/');
  await page.getByLabel('Nome oggetto',{exact:true}).waitFor();
  console.log('Chrome locale senza socket: pagina caricata');
  await page.screenshot({path:'/private/tmp/valigia-desktop.png',fullPage:true});
  console.log('Screenshot: /private/tmp/valigia-desktop.png');
} finally {
  if(browser) await browser.close();
}
